-- Adds the action `club.merge` to the log of the admin (#1345): the editors merge two clubs on a page of Beheer. No row changes.
-- The statement can run again.
-- To undo it on the host: remove the rows with `club.merge` from `audit_log`, and put the list of actions back as it was with `ALTER TABLE audit_log MODIFY COLUMN action enum(...)` without the last value.
ALTER TABLE `audit_log` MODIFY COLUMN `action` enum('item.hide','item.show','item.approve','item.unapprove','article.create','article.update','article.publish','article.unpublish','match.edit','match.undo','match.caught-up','match.differs','match.take-over','match.keep','match.add','match.delete','stadium.save','stadium.reset','club-name.save','club-name.reset','player.stats-differ','player.stats-take-over','player.stats-keep','player.add','player.edit','player.remove','player.field-take-over','player.field-keep','person.edit','person.merge','account.create','account.edit','account.disable','account.enable','club.edit','ground.create','ground.edit','ground-name.save','home-ground.save','gap.mark','gap.renew','gap.unmark','club.merge') NOT NULL;